with not_flagged as (select s.* from stores s where exists (select 1 from orders c where c.store_id = s.id and c.order_date < s.opened_date)) select case when sqft >= 16698 then 'HIGH' else 'LOW' end as sqft_tier, count(distinct region) as distinct_regions, round(avg(sqft), 2) as avg_sqft, approx_percentile(sqft, 0.5) as sqft_p50, count(*) as event_count, sort_array(collect_set(region)) as region_list, round(sum(sqft) / nullif(count(case when region = 'East' then 1 end), 0), 2) as sqft_per_east from not_flagged group by case when sqft >= 16698 then 'HIGH' else 'LOW' end having round(sum(sqft) / nullif(count(case when region = 'East' then 1 end), 0), 2) > 0 order by sqft_p50 asc;
